class Solution {
public:
    long long minCost(string s, vector<int>& cost) {
        long long total = 0, best = 0;
        long long grp[26] = {0};
        for (int i = 0; i < (int)s.size(); i++) {
            total += cost[i];
            grp[s[i]-'a'] += cost[i];
        }
        for (int c = 0; c < 26; c++) best = max(best, grp[c]);
        return total - best;
    }
};

